  count_fact: '12 મેગાપિક્સેલના એક મોબાઇલ ફોટોમાં લગભગ 3.6 કરોડ સંખ્યાઓ હોય છે!',
  inside_title: 'અંદર શું થાય છે?',
  px_inside: 'સ્ક્રીન લાલ, લીલો અને વાદળી પ્રકાશ ભેળવીને દરેક રંગ બનાવે છે. 0 થી 255 સુધીની દરેક સંખ્યા કહે છે કે એ પ્રકાશ કેટલો વાપરવો: (0, 0, 0) કાળો, (255, 255, 255) સફેદ અને (255, 0, 0) પૂરો લાલ. કમ્પ્યુટર સ્માઇલી કે કેરી "જોતું" નથી, તેને ફક્ત સંખ્યાઓનું આ મોટું કોષ્ટક મળે છે. ચિત્રો સાથે કામ કરતું દરેક AI આ જ સંખ્યાઓથી શરૂ કરે છે.',
  f_title: 'એક ફિલ્ટર પસંદ કરો',
  f_identity: 'કોઈ ફેરફાર નહીં', f_blur: 'ઝાંખું', f_sharpen: 'તીક્ષ્ણ', f_edge_h: 'આડી કિનારીઓ', f_edge_v: 'ઊભી કિનારીઓ',
  f_sobel: 'બધી કિનારીઓ (Sobel)', f_emboss: 'ઉપસાવ', f_outline: 'રૂપરેખા', f_custom: 'મારું ફિલ્ટર',
  d_identity: 'ફક્ત વચ્ચેની સંખ્યા 1 છે, એટલે દરેક પિક્સેલ એવો જ રહે છે. પોતાનું ફિલ્ટર બનાવવા માટે સારી શરૂઆત.',
  d_blur: 'દરેક પિક્સેલ પોતાની અને 8 પડોશીઓની સરેરાશ બને છે (9 સંખ્યાઓ ઉમેરો, 9 વડે ભાગો), એટલે અચાનક ફેરફાર નરમ થઈ જાય છે.',
  d_sharpen: 'વચ્ચેનો પિક્સેલ 5 વાર ગણાય છે અને 4 પડોશીઓ બાદ થાય છે, એટલે નાના તફાવત મોટા બને છે અને ચિત્ર વધુ સ્પષ્ટ લાગે છે.',
  d_edge_h: 'ઉપરની હાર ઋણ, નીચેની હાર ધન. જ્યાં તેજ ઉપરથી નીચે બદલાય ત્યાં જવાબ મોટો આવે છે: એ જ આડી કિનારી. સપાટ ભાગમાં 0 (કાળો) આવે છે.',
  d_edge_v: 'ડાબો સ્તંભ ઋણ, જમણો સ્તંભ ધન. જ્યાં તેજ ડાબેથી જમણે બદલાય ત્યાં જવાબ મોટો આવે છે: એ જ ઊભી કિનારી. સપાટ ભાગમાં 0 (કાળો) આવે છે.',
  d_sobel: 'બે ફિલ્ટર વપરાય છે, Gx (ડાબેથી જમણે) અને Gy (ઉપરથી નીચે), પછી પાયથાગોરસની જેમ જોડાય છે: √(Gx² + Gy²). દરેક દિશાની કિનારીઓ ચમકે છે.',
  d_emboss: 'એક ખૂણે ઋણ, સામેના ખૂણે ધન. કિનારીઓ સિક્કા પરના ચિત્ર જેવી ઉપસેલી દેખાય છે.',
  d_outline: 'વચ્ચે 8 અને બધા પડોશી −1. સપાટ ભાગમાં તેઓ એકબીજાને રદ કરીને 0 (કાળો) થાય છે, ફક્ત રૂપરેખા ચમકે છે.',
  d_custom: 'તમારી પોતાની 9 સંખ્યાઓ લખો. શું તમે ફક્ત ત્રાંસી રેખાઓ શોધતું ફિલ્ટર બનાવી શકો?',
