  cnn_title: 'ફીચર મૅપ: CNNનું પહેલું સ્તર શું શોધે છે',
  cnn_intro: 'CNN (કન્વોલ્યુશનલ ન્યુરલ નેટવર્ક) એ ફોટા, ચહેરા અને હસ્તાક્ષર ઓળખતું AI છે. તેનું પહેલું સ્તર ચિત્ર પર ઘણા નાના ફિલ્ટર સરકાવે છે, બરાબર ફિલ્ટર ટૅબની જેમ. દરેક ફિલ્ટર એક નવું ચિત્ર બનાવે છે, જેને ફીચર મૅપ કહે છે: જ્યાં તેની ભાત મળી ત્યાં તેજસ્વી, જ્યાં ન મળી ત્યાં અંધારું.',
  act_label: 'ફિલ્ટર પછી',
  act_relu: 'ReLU (ફક્ત ધન રાખો)',
  act_abs: 'માપ (બંને દિશા)',
  relu_hint: 'ReLU દરેક ઋણ સંખ્યાને 0 કરી દે છે. એટલે ઊભી કિનારીઓનો મૅપ ફક્ત ત્યાં જ ચમકે છે જ્યાં ચિત્ર અંધારા (ડાબે)થી અજવાળા (જમણે) તરફ જાય છે. સાચું CNN ઊલટી દિશા માટે બીજું ફિલ્ટર શીખી લે છે.',
  abs_hint: 'અહીં આપણે ઋણ ચિહ્ન કાઢી નાખીએ છીએ, એટલે અંધારાથી અજવાળા અને અજવાળાથી અંધારા, બંને પ્રકારની કિનારીઓ ચમકે છે.',
  pool_opt: 'મૅક્સ પૂલિંગ 2 × 2 (દર 4 માંથી સૌથી મોટી રાખો: માપ અડધું)',
  fm_v: 'ઊભી કિનારીઓ |', fm_h: 'આડી કિનારીઓ —', fm_d1: 'ત્રાંસી કિનારીઓ ╲', fm_d2: 'ત્રાંસી કિનારીઓ ╱', fm_spot: 'ટપકાં અને પાતળી રેખાઓ', fm_all: 'બધી કિનારીઓ',
  kernel_legend: 'ફિલ્ટરના રંગ: વાદળી = ધન સંખ્યાઓ, નારંગી = ઋણ સંખ્યાઓ. મૅપ જેટલો તેજસ્વી, મેળ એટલો પાકો.',
  pipe_title: 'પિક્સેલથી જવાબ સુધી',
  pipe_1: 'ચિત્ર = સંખ્યાઓ',
  pipe_2: 'સ્તર 1: કિનારીઓ',
  pipe_3: 'સ્તર 2: ખૂણા અને વળાંક',
  pipe_4: 'સ્તર 3: આંખ, પાંદડાં, પૈડાં જેવા ભાગ',
  pipe_5: 'જવાબ: "કેરી" 92%',
  pipe_note: 'ઊંડાં સ્તરો નાની ભાતો જોડીને મોટી ભાતો બનાવે છે. આ ફિલ્ટરની સંખ્યાઓ કોઈ ટાઇપ કરતું નથી: CNN હજારો લેબલવાળા ફોટામાંથી તે જાતે શીખે છે. નવાઈની વાત એ છે કે તેણે શીખેલાં પહેલા સ્તરનાં ફિલ્ટર આ પાનાંનાં કિનારી-ફિલ્ટર જેવાં જ દેખાય છે!',
  g_title: 'આ કયા ફિલ્ટરથી બન્યું?',
  g_intro: 'કમ્પ્યુટરે ચિત્ર પર એક ગુપ્ત ફિલ્ટર લગાવ્યું છે. બંને ચિત્રોની સરખામણી કરો અને ફિલ્ટર પસંદ કરો.',
