  g_wrong: 'થોડું ચૂકી ગયા. એ "{name}" હતું.',
  g_tip: 'સૂચન: નવા પડકાર માટે ઉપર ચિત્ર કે પિક્સેલની સંખ્યા બદલો.',
  help_title: 'કેવી રીતે વાપરવું / વર્ગ માટે વિચારો',
  help_1: '"અંક 7" એક લીટીમાં 8 કે 16 પિક્સેલ પર લો અને "ચિત્ર પર સંખ્યાઓ" ચાલુ કરો. વર્ગને પૂછો: શું ફક્ત સંખ્યાઓ જોઈને અંક ઓળખી શકાય? (હસ્તાક્ષરના જાણીતા ડેટાસેટ 28 × 28 પિક્સેલના હોય છે.)',
  help_2: 'સ્માઇલીની કિનારી પરના પિક્સેલ પર ટૅપ કરો અને તેના 7 × 7 પડોશીઓ જુઓ: સંખ્યાઓમાં અચાનક મોટો કૂદકો એટલે કિનારી.',
  help_3: 'ફિલ્ટર ટૅબમાં મોટી સ્ક્રીન પર "ફિલ્ટર સરકાવો" દબાવો અને બતાવો કે દરેક જગ્યાએ એ જ 9 સંખ્યાઓ વપરાય છે.',
  help_4: 'વર્ગ પ્રવૃત્તિ "કમ્પ્યુટર બનો": વર્કશીટ પ્રિન્ટ કરો (શિક્ષક માટે જવાબો સાથે), વિદ્યાર્થીઓની જોડીઓ હાથથી 5 × 5 આઉટપુટ શોધે, પછી ઍપમાં ચકાસે.',
