  cnn_intro: 'CNN (କନ୍ଭୋଲ୍ୟୁସନାଲ୍ ନ୍ୟୁରାଲ୍ ନେଟୱର୍କ) ହେଉଛି ଫଟୋ, ମୁହଁ ଓ ହାତଲେଖା ଚିହ୍ନୁଥିବା AI। ଏହାର ପ୍ରଥମ ସ୍ତର ଛବି ଉପରେ ଅନେକ ଛୋଟ ଫିଲ୍ଟର ଘୁଞ୍ଚାଏ, ଠିକ୍ ଫିଲ୍ଟର ଟ୍ୟାବ୍ ପରି। ପ୍ରତ୍ୟେକ ଫିଲ୍ଟର ଗୋଟିଏ ନୂଆ ଛବି ତିଆରି କରେ, ଯାହାକୁ ଫିଚର୍ ମ୍ୟାପ୍ କୁହାଯାଏ: ଯେଉଁଠି ତା’ର ନମୁନା ମିଳିଲା ସେଠି ଉଜ୍ଜ୍ୱଳ, ଯେଉଁଠି ମିଳିଲା ନାହିଁ ସେଠି ଅନ୍ଧାର।',
