  pipe_note: 'ଗଭୀର ସ୍ତରଗୁଡ଼ିକ ଛୋଟ ନମୁନା ଯୋଡ଼ି ବଡ଼ ନମୁନା ତିଆରି କରନ୍ତି। ଏହି ଫିଲ୍ଟର ସଂଖ୍ୟା କେହି ଟାଇପ୍ କରନ୍ତି ନାହିଁ: CNN ହଜାର ହଜାର ଲେବଲ୍ ଥିବା ଫଟୋରୁ ନିଜେ ଶିଖେ। ଆଶ୍ଚର୍ଯ୍ୟର କଥା, ତା’ର ଶିଖା ପ୍ରଥମ ସ୍ତରର ଫିଲ୍ଟରଗୁଡ଼ିକ ଏହି ପୃଷ୍ଠାର ଧାର ଫିଲ୍ଟର ପରି ହିଁ ଦେଖାଯାଏ!',
