  f_identity: 'ಬದಲಾವಣೆ ಇಲ್ಲ', f_blur: 'ಮಸುಕು', f_sharpen: 'ಚೂಪು', f_edge_h: 'ಅಡ್ಡ ಅಂಚುಗಳು', f_edge_v: 'ಲಂಬ ಅಂಚುಗಳು',
  f_sobel: 'ಎಲ್ಲಾ ಅಂಚುಗಳು (Sobel)', f_emboss: 'ಉಬ್ಬು', f_outline: 'ಹೊರರೇಖೆ', f_custom: 'ನನ್ನ ಫಿಲ್ಟರ್',
  d_identity: 'ಮಧ್ಯದ ಸಂಖ್ಯೆ ಮಾತ್ರ 1, ಆದ್ದರಿಂದ ಪ್ರತಿ ಪಿಕ್ಸೆಲ್ ಹಾಗೆಯೇ ಇರುತ್ತದೆ. ನಿಮ್ಮದೇ ಫಿಲ್ಟರ್ ಮಾಡಲು ಉತ್ತಮ ಆರಂಭ.',
  d_blur: 'ಪ್ರತಿ ಪಿಕ್ಸೆಲ್ ತನ್ನ ಮತ್ತು ತನ್ನ 8 ನೆರೆಯವುಗಳ ಸರಾಸರಿ ಆಗುತ್ತದೆ (9 ಸಂಖ್ಯೆ ಕೂಡಿಸಿ 9 ರಿಂದ ಭಾಗಿಸಿ), ಆದ್ದರಿಂದ ಹಠಾತ್ ಬದಲಾವಣೆಗಳು ಮೃದುವಾಗುತ್ತವೆ.',
  d_sharpen: 'ಮಧ್ಯದ್ದನ್ನು 5 ಸಲ ಎಣಿಸಿ 4 ನೆರೆಯವುಗಳನ್ನು ಕಳೆಯಲಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಸಣ್ಣ ವ್ಯತ್ಯಾಸಗಳು ದೊಡ್ಡದಾಗಿ ಚಿತ್ರ ಹೆಚ್ಚು ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣುತ್ತದೆ.',
  d_edge_h: 'ಮೇಲಿನ ಸಾಲು ಋಣ, ಕೆಳಗಿನ ಸಾಲು ಧನ. ಹೊಳಪು ಮೇಲಿನಿಂದ ಕೆಳಗೆ ಬದಲಾಗುವಲ್ಲಿ ಉತ್ತರ ದೊಡ್ಡದು: ಅದೇ ಅಡ್ಡ ಅಂಚು. ಸಮತಟ್ಟಾದ ಭಾಗಗಳಲ್ಲಿ 0 (ಕಪ್ಪು) ಬರುತ್ತದೆ.',
  d_edge_v: 'ಎಡ ಕಾಲಂ ಋಣ, ಬಲ ಕಾಲಂ ಧನ. ಹೊಳಪು ಎಡದಿಂದ ಬಲಕ್ಕೆ ಬದಲಾಗುವಲ್ಲಿ ಉತ್ತರ ದೊಡ್ಡದು: ಅದೇ ಲಂಬ ಅಂಚು. ಸಮತಟ್ಟಾದ ಭಾಗಗಳಲ್ಲಿ 0 (ಕಪ್ಪು) ಬರುತ್ತದೆ.',
  d_sobel: 'ಎರಡು ಫಿಲ್ಟರ್‌ಗಳು, Gx (ಎಡದಿಂದ ಬಲ) ಮತ್ತು Gy (ಮೇಲಿನಿಂದ ಕೆಳಗೆ), ನಂತರ ಪೈಥಾಗೊರಸ್‌ನಂತೆ ಸೇರಿಸಲಾಗುತ್ತದೆ: √(Gx² + Gy²). ಎಲ್ಲಾ ದಿಕ್ಕಿನ ಅಂಚುಗಳು ಹೊಳೆಯುತ್ತವೆ.',
  d_emboss: 'ಒಂದು ಮೂಲೆಯಲ್ಲಿ ಋಣ, ಎದುರಿನ ಮೂಲೆಯಲ್ಲಿ ಧನ. ಅಂಚುಗಳು ನಾಣ್ಯದ ಮೇಲಿನ ಚಿತ್ರದಂತೆ ಉಬ್ಬಿದಂತೆ ಕಾಣುತ್ತವೆ.',
  d_outline: 'ಮಧ್ಯದಲ್ಲಿ 8, ಎಲ್ಲಾ ನೆರೆಯವು −1. ಸಮತಟ್ಟಾದ ಭಾಗಗಳಲ್ಲಿ ಇವು ರದ್ದಾಗಿ 0 (ಕಪ್ಪು) ಆಗುತ್ತವೆ; ಹೊರರೇಖೆಗಳು ಮಾತ್ರ ಹೊಳೆಯುತ್ತವೆ.',
  d_custom: 'ನಿಮ್ಮದೇ 9 ಸಂಖ್ಯೆಗಳನ್ನು ಟೈಪ್ ಮಾಡಿ. ಓರೆ ಗೆರೆಗಳನ್ನು ಮಾತ್ರ ಹುಡುಕುವ ಫಿಲ್ಟರ್ ಮಾಡಬಲ್ಲಿರಾ?',
