  m_border: 'ಅಂಚಿನಲ್ಲಿ ಇಲ್ಲದ ನೆರೆಯವು ಹತ್ತಿರದ ಅಂಚಿನ ಪಿಕ್ಸೆಲ್‌ನ ನಕಲು ತೆಗೆದುಕೊಳ್ಳುತ್ತವೆ.',
  ws_title: 'ಕಂಪ್ಯೂಟರ್ ಆಗಿ: ಕೈಯಿಂದ ಫಿಲ್ಟರ್ ಹಾಕಿ',
  ws_name: 'ಹೆಸರು: ____________________   ತರಗತಿ: ______   ದಿನಾಂಕ: __________',
  ws_steps: 'ಪ್ರತಿ ಬಿಳಿ ಚೌಕಕ್ಕೂ (ಚಿತ್ರದ ಒಳಗಿನ 5 × 5 ಭಾಗ): ಫಿಲ್ಟರನ್ನು ಆ ಚೌಕ ಮತ್ತು ಅದರ 8 ನೆರೆಯವುಗಳ ಮೇಲೆ ಇಡಿ, ಪ್ರತಿ ಜೋಡಿ ಸಂಖ್ಯೆಗಳನ್ನು ಗುಣಿಸಿ, 9 ಉತ್ತರಗಳನ್ನು ಕೂಡಿಸಿ, ನಂತರ ಫಿಲ್ಟರ್ ಕೆಳಗಿನ ನಿಯಮ ಪಾಲಿಸಿ. ಉತ್ತರವನ್ನು ಔಟ್‌ಪುಟ್ ಜಾಲದ ಅದೇ ಚೌಕದಲ್ಲಿ ಬರೆಯಿರಿ.',
