  cnn_title: 'ಫೀಚರ್ ಮ್ಯಾಪ್‌ಗಳು: CNN ನ ಮೊದಲ ಪದರ ಏನು ಹುಡುಕುತ್ತದೆ',
  cnn_intro: 'CNN (ಕನ್ವಲ್ಯೂಷನಲ್ ನ್ಯೂರಲ್ ನೆಟ್‌ವರ್ಕ್) ಎಂಬುದು ಫೋಟೋ, ಮುಖ ಮತ್ತು ಕೈಬರಹ ಗುರುತಿಸುವ AI. ಅದರ ಮೊದಲ ಪದರ ಚಿತ್ರದ ಮೇಲೆ ಅನೇಕ ಸಣ್ಣ ಫಿಲ್ಟರ್‌ಗಳನ್ನು ಸರಿಸುತ್ತದೆ, ಫಿಲ್ಟರ್‌ಗಳ ಟ್ಯಾಬ್‌ನಲ್ಲಿರುವಂತೆಯೇ. ಪ್ರತಿ ಫಿಲ್ಟರ್ ಫೀಚರ್ ಮ್ಯಾಪ್ ಎಂಬ ಹೊಸ ಚಿತ್ರ ಮಾಡುತ್ತದೆ: ಅದರ ಮಾದರಿ ಸಿಕ್ಕಲ್ಲಿ ಹೊಳಪು, ಸಿಗದಲ್ಲಿ ಕತ್ತಲು.',
  act_label: 'ಫಿಲ್ಟರ್ ನಂತರ',
