  relu_hint: 'ReLU ಪ್ರತಿ ಋಣ ಸಂಖ್ಯೆಯನ್ನು 0 ಮಾಡುತ್ತದೆ. ಆದ್ದರಿಂದ ಲಂಬ ಅಂಚಿನ ಮ್ಯಾಪ್, ಚಿತ್ರ ಕತ್ತಲಿನಿಂದ (ಎಡ) ಬೆಳಕಿನ (ಬಲ) ಕಡೆಗೆ ಹೋಗುವಲ್ಲಿ ಮಾತ್ರ ಹೊಳೆಯುತ್ತದೆ. ನಿಜವಾದ CNN ವಿರುದ್ಧ ದಿಕ್ಕಿಗೆ ಇನ್ನೊಂದು ಫಿಲ್ಟರ್ ಕಲಿಯುತ್ತದೆ.',
  abs_hint: 'ಇಲ್ಲಿ ನಾವು ಮೈನಸ್ ಚಿಹ್ನೆ ತೆಗೆಯುತ್ತೇವೆ, ಆದ್ದರಿಂದ ಕತ್ತಲಿನಿಂದ ಬೆಳಕು ಮತ್ತು ಬೆಳಕಿನಿಂದ ಕತ್ತಲು, ಎರಡೂ ರೀತಿಯ ಅಂಚುಗಳು ಹೊಳೆಯುತ್ತವೆ.',
  pool_opt: 'ಮ್ಯಾಕ್ಸ್ ಪೂಲಿಂಗ್ 2 × 2 (ಪ್ರತಿ 4 ರಲ್ಲಿ ದೊಡ್ಡದನ್ನು ಇಡಿ: ಗಾತ್ರ ಅರ್ಧ)',
  fm_v: 'ಲಂಬ ಅಂಚುಗಳು |', fm_h: 'ಅಡ್ಡ ಅಂಚುಗಳು —', fm_d1: 'ಓರೆ ಅಂಚುಗಳು ╲', fm_d2: 'ಓರೆ ಅಂಚುಗಳು ╱', fm_spot: 'ಚುಕ್ಕೆಗಳು ಮತ್ತು ತೆಳು ಗೆರೆಗಳು', fm_all: 'ಎಲ್ಲಾ ಅಂಚುಗಳು',
  kernel_legend: 'ಫಿಲ್ಟರ್ ಬಣ್ಣಗಳು: ನೀಲಿ = ಧನ ಸಂಖ್ಯೆಗಳು, ಕಿತ್ತಳೆ = ಋಣ ಸಂಖ್ಯೆಗಳು. ಮ್ಯಾಪ್ ಎಷ್ಟು ಹೊಳೆದರೆ, ಹೊಂದಾಣಿಕೆ ಅಷ್ಟು ಬಲವಾದದ್ದು.',
