  pipe_4: 'ಪದರ 3: ಕಣ್ಣು, ಎಲೆ, ಚಕ್ರದಂತಹ ಭಾಗಗಳು',
  pipe_5: 'ಉತ್ತರ: "ಮಾವಿನ ಹಣ್ಣು" 92%',
  pipe_note: 'ಆಳದ ಪದರಗಳು ಸಣ್ಣ ಮಾದರಿಗಳನ್ನು ಸೇರಿಸಿ ದೊಡ್ಡ ಮಾದರಿಗಳನ್ನು ಮಾಡುತ್ತವೆ. ಈ ಫಿಲ್ಟರ್ ಸಂಖ್ಯೆಗಳನ್ನು ಯಾರೂ ಟೈಪ್ ಮಾಡುವುದಿಲ್ಲ: ಸಾವಿರಾರು ಲೇಬಲ್ ಇರುವ ಫೋಟೋಗಳಿಂದ CNN ಅವುಗಳನ್ನು ತಾನೇ ಕಲಿಯುತ್ತದೆ. ಅಚ್ಚರಿಯೆಂದರೆ, ಅದು ಕಲಿಯುವ ಮೊದಲ ಪದರದ ಫಿಲ್ಟರ್‌ಗಳು ಈ ಪುಟದ ಅಂಚಿನ ಫಿಲ್ಟರ್‌ಗಳಂತೆಯೇ ಕಾಣುತ್ತವೆ!',
