  help_4: 'ತರಗತಿ ಚಟುವಟಿಕೆ "ಕಂಪ್ಯೂಟರ್ ಆಗಿ": ವರ್ಕ್‌ಶೀಟ್ ಮುದ್ರಿಸಿ (ಶಿಕ್ಷಕರಿಗೆ ಉತ್ತರಗಳೊಂದಿಗೆ), ವಿದ್ಯಾರ್ಥಿಗಳು ಜೋಡಿಯಾಗಿ ಕೈಯಿಂದ 5 × 5 ಔಟ್‌ಪುಟ್ ಲೆಕ್ಕ ಮಾಡಲಿ, ನಂತರ ಆ್ಯಪ್‌ನಲ್ಲಿ ಪರಿಶೀಲಿಸಲಿ.',
