  help_3: 'ഫിൽട്ടറുകൾ ടാബിൽ വലിയ സ്ക്രീനിൽ "ഫിൽട്ടർ നീക്കൂ" അമർത്തി, എല്ലായിടത്തും അതേ 9 സംഖ്യകളാണ് ഉപയോഗിക്കുന്നതെന്ന് കാണിക്കൂ.',
